// neon.js — NÉON, a minimalist brick breaker (zero dependencies).
//
// This file INTENTIONALLY mixes game logic and rendering in a few places
// (see ISSUES.md #2): brick collision detection currently lives inside the
// draw loop `frame()`. This is deliberate debt, ripe for a refactor.
//
// The module runs nothing on import: only `boot()` touches the DOM. Pure
// logic can therefore be imported from the tests (`node --test`) without a
// browser.

import { palette, brickColor } from './theme.js';
import { createGlowMap, drawGlow, GLOW_W, GLOW_H } from './bloom.js';

// --- Axis convention -------------------------------------------------------

// Screen coordinates, as the canvas defines them: the origin is the TOP-LEFT
// corner and **Y GROWS DOWNWARD**. So `y = 0` is the ceiling, `y = HEIGHT` the
// line through which the ball is lost, and a ball climbing toward the bricks
// has a NEGATIVE `vy`. Every sign in this file follows from that single
// choice — the launch velocity, each bounce, and the paddle test `vy > 0`.
//
// The constants below name the sign a velocity component takes per heading.
// Assert against them rather than against a bare `-1` / `1`: a test reading
// `Math.sign(ball.vy) === UP` states its intent, where a hard-coded `-1` only
// states an arithmetic fact and quietly means the opposite if the convention
// ever flips.
//
//   UP    (-1)  toward the ceiling and the bricks
//   DOWN  (+1)  toward the paddle and the loss line
//   LEFT  (-1)  toward x = 0
//   RIGHT (+1)  toward x = WIDTH

export const UP = -1;
export const DOWN = 1;
export const LEFT = -1;
export const RIGHT = 1;

// --- Field constants -------------------------------------------------------

export const WIDTH = 640;
export const HEIGHT = 480;

export const PADDLE_W = 96;
export const PADDLE_H = 12;
export const PADDLE_Y = HEIGHT - 32;

export const BALL_R = 7;

export const BRICK_ROWS = 5;
export const BRICK_COLS = 8;
export const BRICK_W = 72;
export const BRICK_H = 20;
export const BRICK_GAP = 8;
export const BRICK_TOP = 48;

const STORAGE_KEY = 'neon.best';

// --- State construction ----------------------------------------------------

// Builds the brick grid for a given level.
// The higher the level, the more points bricks are worth.
export function makeBricks(level = 1) {
  const bricks = [];
  const offsetX = (WIDTH - (BRICK_COLS * (BRICK_W + BRICK_GAP) - BRICK_GAP)) / 2;
  for (let row = 0; row < BRICK_ROWS; row++) {
    for (let col = 0; col < BRICK_COLS; col++) {
      bricks.push({
        x: offsetX + col * (BRICK_W + BRICK_GAP),
        y: BRICK_TOP + row * (BRICK_H + BRICK_GAP),
        w: BRICK_W,
        h: BRICK_H,
        row,
        alive: true,
        points: (BRICK_ROWS - row) * 10 * level,
      });
    }
  }
  return bricks;
}

// Ball speed as a function of the level (ramps up with each level).
export function ballSpeed(level = 1) {
  return 260 + (level - 1) * 90;
}

// Creates a fresh game state.
export function createState(level = 1) {
  const speed = ballSpeed(level);
  return {
    level,
    lives: 3,
    score: 0,
    combo: 0,
    best: 0,
    running: false,
    paddle: { x: (WIDTH - PADDLE_W) / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H },
    ball: { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: speed * 0.5, vy: -speed },
    bricks: makeBricks(level),
  };
}

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Rendering (DOM): brick collision logic STILL mixed in here ------------

// Main render loop. For each live brick we test collision AND draw in the same
// pass: this is where logic and rendering are entangled.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: collision + bounce + score + drawing, all in one place.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    if (collides(state.ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      // BUG (#1): the ball is NOT deflected here. Only the walls and the paddle
      // bounce (in step()); bricks were never given a bounce. So the ball plows
      // straight through a column head-on AND straight through the side of a
      // row. Fix = a real per-face bounce (flip vy on a top/bottom hit, vx on a
      // side hit) plus pushing the ball back out of the brick.
    }

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

// --- Boot (browser entry point) --------------------------------------------

// Starts the game: wires up the canvas, the mouse and the animation loop.
// The only function that depends on the DOM; never called on import.
export function boot(doc = document) {
  const canvas = doc.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  const state = createState(1);
  state.best = loadBest(doc.defaultView?.localStorage ?? globalThis.localStorage);
  state.running = true;

  // Glow pass: a coarse offscreen light map, stretched over the field.
  const offscreen = doc.createElement('canvas');
  offscreen.width = GLOW_W;
  offscreen.height = GLOW_H;
  const glow = {
    map: createGlowMap(),
    image: offscreen.getContext('2d').createImageData(GLOW_W, GLOW_H),
  };

  // Move the paddle with the mouse.
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left - state.paddle.w / 2;
    state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, x));
  });

  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;

    if (state.running) {
      const lost = step(state, dt);
      if (lost) {
        state.lives -= 1;
        state.combo = 0;
        if (state.lives <= 0) {
          state.best = saveBest(globalThis.localStorage, state.score);
          Object.assign(state, createState(state.level));
          state.best = loadBest(globalThis.localStorage);
        } else {
          // relaunch the ball
          state.ball = createState(state.level).ball;
        }
      }

      // Level cleared: all bricks broken
      if (state.bricks.every((b) => !b.alive)) {
        state.level += 1;
        state.bricks = makeBricks(state.level);
        state.ball = createState(state.level).ball;
      }
    }

    frame(ctx, state);
    drawGlow(ctx, glow, state, WIDTH, HEIGHT, offscreen);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  return state;
}

// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.

// theme.js — NÉON color palette.
//
// Intent: keep ALL colors here so we can later derive variants easily
// (e.g. a night mode). In practice the migration is not finished: several
// colors are still hard-coded in neon.js (see ISSUES.md #6). This palette is
// therefore a starting point, not yet the single source of truth.

export const palette = {
  background: '#0a0118',
  paddle: '#00e5ff',
  ball: '#39ff14',
  text: '#f5f5ff',
  // Brick colors per row (top to bottom).
  bricks: ['#ff2d95', '#ff8a00', '#ffe600', '#39ff14', '#00e5ff'],
};

// Returns the color of a brick based on its row.
// (Safe if the number of rows exceeds the palette: we wrap around.)
export function brickColor(row) {
  return palette.bricks[row % palette.bricks.length];
}

Now I'll implement the fix. I'll add a pure, testable `brickHit` function that handles the collision resolution, addressing all the cases described in ISSUES.md #1.

Key design considerations from the issue:
1. **Per face**: flip the axis with the smaller penetration
2. **Corner**: equal penetrations → flip both
3. **Push out**: reposition ball outside the brick to avoid sticky bounce
4. **Neighbours**: since gaps are 8px and ball is 14px across, one ball can overlap two bricks in the same pass. The bounce must apply exactly once — flipping the same component twice cancels out.

The neighbour problem is the trickiest. The issue says "the bounce must apply exactly once (`vy = -vy` applied twice cancels out)". 

My approach: `brickHit` returns a per-brick bounce result indicating which component(s) to flip (or no flip). Then in `frame()`, I compute the aggregate. But the challenge is that if two adjacent bricks both report `flip vy`, applying both would cancel.

Let me think about this carefully. The cleanest way per the issue is to make `brickHit` return *which* components to flip. But there's the ambiguity: should the ball position/momentum be updated inside `brickHit` or in `frame()`?

Let me design `brickHit` to return the bounce information rather than mutating, OR make it collect the whole update. Actually, the issue #2 suggests extracting `brickHit(ball, bricks)` as a pure function. Let me create a function that takes the ball and the set of overlapping bricks and returns a resolution.

Let me think about the neighbour case. Bricks in the same row are separated by a gap of 8px. The ball radius is 7px → 14px diameter, which is larger than the 8px gap. So a ball hitting the vertical seam between two horizontally-adjacent bricks can overlap both at once.

If a ball is coming down and hits two bricks side by side (same row), the collision with both would report "top face hit → flip vy". If I apply vy = -vy for both, it flips twice and cancels.

The issue says: apply the flip exactly once. So I need to make the flip idempotent. One standard approach: only flip a component if the ball is currently moving toward that brick face. But in the side-by-side same-row case, the ball is moving down (toward the top face of both), so flipping once is correct.

Actually a robust approach used in many brick breakers: for each collision, compute the bounce, but before flipping, check the direction. Since the ball is moving toward the face it's penetrating, we flip. If two bricks both require flipping `vy` (same downward motion), we should flip only once.

The way to avoid double-flip: track which components were already flipped during this pass. If `brickHit` is called once with all overlapping bricks (not per brick), we can aggregate.

Let me design it as: `brickHit(ball, bricks)` scans all live bricks, finds overlapping ones, and for the overlap computes penetration on each axis, picks the ball's velocity response once per axis. Actually, let me make it simpler and robust.

Let me write a `brickHit(ball, bricks)` that:
- iterates over bricks that collide
- For each, computes penetrationX and penetrationY
- Determines the face (smaller penetration → that axis is the hit face)
- Marks the brick destroyed
- Returns the set of axes to flip as `{x: bool, y: bool}` aggregated with OR (to avoid double-flip), and pushes the ball out.

Wait, but push-out also has the neighbour problem. If the ball overlaps two bricks side-by-side and we push it out separately for each... Actually for side-by-side bricks in a row, the ball drops onto the top faces. Penetration on Y is small (it's just sinking a bit below the top edge), penetration on X... the ball center may be over the seam, overlapping both horizontally. For brick on left, penetrationX might be small (ball left edge near brick right edge) — but that's a side face, not top. Hmm, this gets complicated.

Let me reconsider. The issue's guidance:
- **per face**: the axis with the *smaller* penetration is the face that was hit — this is for determining which face of a SINGLE brick.
- For side-by-side same-row neighbors: ball moving down, hits top faces of both. For each brick, Y penetration is smaller (top face). So both report "flip vy". Apply once.

For the push-out: I need to reposition the ball so it's fully outside the brick being hit. For a top-face hit, push ball up so `ball.y + ball.r <= brick.y`. If done for the left brick, the ball moves up; then the right brick also overlaps but once the ball is pushed up above both top faces, the next frame neither overlaps. But if in the same pass I process the right brick AFTER pushing out of the left, the right brick may no longer overlap → I must compute all overlaps *before* pushing out.

So the algorithm:
1. Collect all overlapping live bricks first (before any mutation).
2. If none, return null.
3. Determine the aggregate hit face across all overlapping bricks.
4. Apply one bounce (flip the appropriate component(s)), push the ball out.
5. Mark all overlapping bricks destroyed, count score for all (or just... well each brick).

Hmm, but marking multiple bricks from one pass — that's existing behavior essentially (one at a time per frame though). Let me keep it reasonable.

Actually, re-reading the issue more carefully, I think a per-brick approach with the direction check is the standard robust solution. Let me reconsider the "apply exactly once" requirement.

The cleanest solution that satisfies "apply exactly once": flip a component only if the ball is moving in the direction that would cause re-penetration. For a top-face hit (ball moving down, penetrating from above), `vy > 0`, we set `vy = -|vy|`. For a bottom-face hit, `vy < 0`, set `vy = |vy|`. For a left-face hit (ball moving right), `vx > 0`, set `vx = -|vx|`. For right-face, `vx < 0`, set `vx = |vx|`.

If the ball overlaps two side-by-side bricks while moving down, both have `vy > 0` and both tell us to flip vy by negation. If I do `vy = -|vy|` for the first, then for the second I already compute `-|vy|` which equals the current value → no cancelation. The key is I set it to the *absolute* magnitude, not `vy = -vy`. So applying it twice gives `-|vy|` both times → stable. That resolves the neighbour issue elegantly!

So the trick: rather than `flipAxis` toggling a boolean, use "set the component to the correct sign based on the face". This makes it idempotent. 

Now for push-out: for each overlapping brick, push the ball out along the hit axis. But if two bricks, does pushing out of one interfere? If I push up out of the top face of the left brick, the ball is now above both (since they're in the same row, same top edge Y). So the right brick also gets resolved. But I should push based on the minimum penetration among all... Actually let me push out in a single resolution.

Let me design `brickHit(ball, bricks)` to handle the aggregate:

```
export function brickHit(ball, bricks) {
  let destroyed = [];
  let hitY = true; // which axis to bounce... 
  ...
}
```

Hmm, let me think about how to combine multiple overlaps into one resolution smoothly.

Approach: 
- For each live overlapping brick, compute penetration on X and Y (which face).
- Track the smallest penetration among all → that determines the primary face to bounce and push out.
- Also handle corner case where one brick gives equal penetrations.

Actually, dealing with the aggregate definitively: The ball can overlap multiple bricks around the seam. The most important thing is the bounce happens once and the ball gets pushed out cleanly. 

Let me go with: iterate overlapping bricks, bounce per brick but in an idempotent fashion (set sign based on face rather than toggle), and push out per brick. Pushing out per brick: if overlapping two same-row top faces, pushing out the first (move up) puts the ball above both, so when I check/push the second it's already satisfied. But I computed overlaps ahead of time so I don't lose it. Actually push-out just clamps position; doing it twice toward the same direction is fine.

Let me define penetration:
- penLeft = brick.x + brick.w - (ball.x - ball.r)  // overlap on left side → ball should go left? no.
- Actually: penetration on X into brick from the side.

Standard: 
- overlapX = min ball extension into brick in +x direction vs -x:
  - dxRight = ball.x + ball.r - brick.x  // how far ball's right edge past brick's left edge
  - dxLeft = brick.x + brick.w - (ball.x - ball.r) // how far ball's left edge past brick's right edge
  - penetrationX = min(dxRight, dxLeft)
- overlapY:
  - dyBottom = ball.y + ball.r - brick.y
  - dyTop = brick.y + brick.h - (ball.y - ball.r)
  - penetrationY = min(dyBottom, dyTop)

Face determination for single brick:
- if penetrationX < penetrationY → side hit (flip vx, push horizontally)
  - direction: if dxRight < dxLeft → ball's right edge penetrated brick's left → ball moving right → bounce vx to negative (left). push ball left: ball.x = brick.x - ball.r
  - else → ball's left edge penetrated brick's right → vx positive. push ball right: ball.x = brick.x + brick.w + ball.r
- else if penetrationY < penetrationX → top/bottom (flip vy, push vertically)
  - if dyBottom < dyTop → ball's bottom edge penetrated brick top → ball above, moving down → vy negative. push up: ball.y = brick.y - ball.r
  - else → ball from below → vy positive. push down: ball.y = brick.y + brick.h + ball.r
- else (equal) → corner/edge diagonal → flip both.

Now the idempotency: instead of computing exact side/top each time and flipping a toggle flag, I accumulate the required final sign for vx and vy across all overlapping bricks, then apply once at the end. Let me track:
- `resolvedVx`: a value or "we need to flip vx"
- Actually, let me accumulate: keep target vx/vy sign based on hits, and only flip if not already. Since idempotent with absolute values, I can just apply per hit.

Let me keep it clean with a resolve-once approach that's still simple:

```
export function brickHit(ball, bricks) {
  let bounced = false;
  // Iterate and for each overlapping brick compute desired outcome.
  for (const brick of bricks) {
    if (!brick.alive) continue;
    if (!collides(ball, brick)) continue;
    brick.alive = false;
    bounced = true;

    const penRight = ball.x + ball.r - brick.x;          // right edge past brick left, ball to the left → moving right
    const penLeft  = brick.x + brick.w - (ball.x - ball.r); // left edge past brick right, ball to the right → moving left
    const penBottom= ball.y + ball.r - brick.y;          // bottom past top, ball above → moving down
    const penTop   = brick.y + brick.h - (ball.y - ball.r); // top past bottom, ball below → moving up

    const penX = Math.min(penRight, penLeft);
    const penY = Math.min(penBottom, penTop);

    if (penY < penX) {
      // horizontal face: flip vy, push vertically
      if (penBottom <= penTop) {
        // moving down, ball above
        ball.vy = -Math.abs(ball.vy);
        ball.y = brick.y - ball.r;
      } else {
        ball.vy = Math.abs(ball.vy);
        ball.y = brick.y + brick.h + ball.r;
      }
    } else if (penX < penY) {
      // vertical face: flip vx, push horizontally
      if (penRight <= penLeft) {
        ball.vx = -Math.abs(ball.vx);
        ball.x = brick.x - ball.r;
      } else {
        ball.vx = Math.abs(ball.vx);
        ball.x = brick.x + brick.w + ball.r;
      }
    } else {
      // corner: flip both
      if (penBottom <= penTop) ball.vy = -Math.abs(ball.vy); else ball.vy = Math.abs(ball.vy);
      if (penRight <= penLeft) ball.vx = -Math.abs(ball.vx); else ball.vx = Math.abs(ball.vx);
      // push out toward the smaller... both equal, push along the dominant motion
      if (Math.abs(ball.vy) >= Math.abs(ball.vx)) {
        ball.y = (penBottom <= penTop) ? brick.y - ball.r : brick.y + brick.h + ball.r;
      } else {
        ball.x = (penRight <= penLeft) ? brick.x - ball.r : brick.x + brick.w + ball.r;
      }
    }
  }
  return bounced;
}
```

