edits.newText:
test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- brickHit: the ball bounces off bricks instead of plowing through (#1) --

// A brick centered in the field so there is room to push the ball out on both
// the x and y axes.
function centeredBrick() {
  return { x: 250, y: 200, w: 72, h: 20, alive: true, points: 10 };
}

test('brickHit: ball from above bounces down (top face) and is pushed out', () => {
  const brick = centeredBrick();
  const ball = { x: 286, y: 190, r: BALL_R, vx: 0, vy: 300 };
  const broken = brickHit(ball, [brick]);
  assert.deepEqual(broken, [brick]);
  assert.equal(brick.alive, false);
  assert.ok(ball.vy < 0, 'vy should flip upward on a top-face hit');
  assert.equal(ball.y + ball.r, brick.y, 'ball should sit just above the brick');
});

test('brickHit: ball from below bounces up (bottom face)', () => {
  const brick = centeredBrick();
  const ball = { x: 286, y: 226, r: BALL_R, vx: 0, vy: -300 };
  brickHit(ball, [brick]);
  assert.ok(ball.vy > 0, 'vy should flip downward on a bottom-face hit');
  assert.equal(ball.y - ball.r, brick.y + brick.h);
});

test('brickHit: ball from the side bounces horizontally (side face)', () => {
  const brick = centeredBrick();
  // Ball sits to the LEFT of the brick, moving right into its left face.
  const ball = { x: 243, y: 210, r: BALL_R, vx: 300, vy: 0 };
  brickHit(ball, [brick]);
  assert.ok(ball.vx < 0, 'vx should flip leftward on a left-face hit');
  assert.equal(ball.x + ball.r, brick.x, 'ball should sit just left of the brick');
});

test('brickHit: corner hit flips both components', () => {
  const brick = centeredBrick();
  // Ball approaches the top-left corner diagonally; penetrations are equal.
  const ball = { x: 243, y: 193, r: BALL_R, vx: 300, vy: 300 };
  brickHit(ball, [brick]);
  assert.ok(ball.vx < 0 && ball.vy < 0, 'both components should flip on a corner hit');
  assert.ok(!collides(ball, brick), 'ball must be pushed clear of the brick');
});

test('brickHit: two adjacent bricks in the same seam bounce exactly once', () => {
  // Two bricks side by side (gap 8 < ball diameter 14), so one ball can overlap
  // both while dropping onto them. The bounce must apply only once per axis,
  // otherwise vy would flip back and the ball would plow through.
  const brickA = { x: 250, y: 200, w: 72, h: 20, alive: true, points: 10 };
  const brickB = { x: 250 + 72 + 8, y: 200, w: 72, h: 20, alive: true, points: 10 };
  // Center the ball over the seam, slightly above the top edge.
  const ball = { x: 330, y: 196, r: BALL_R, vx: 0, vy: 300 };
  const broken = brickHit(ball, [brickA, brickB]);
  assert.equal(broken.length, 2, 'both overlapping bricks are broken');
  assert.ok(ball.vy < 0, 'vy should end up flipped exactly once (upward)');
  assert.ok(!collides(ball, brickA) && !collides(ball, brickB), 'ball cleared of both');
});

test('brickHit: dead bricks are ignored and nothing bounces if none collide', () => {
  const dead = { x: 250, y: 200, w: 72, h: 20, alive: false, points: 10 };
  const far = { x: 50, y: 50, w: 72, h: 20, alive: true, points: 10 };
  const ball = { x: 286, y: 210, r: BALL_R, vx: 0, vy: 0 };
  const broken = brickHit(ball, [dead, far]);
  assert.equal(broken.length, 0);
  assert.equal(far.alive, true);
  assert.equal(ball.vx, 0);
  assert.equal(ball.vy, 0);
});

